//! Comparable movement-only replication workload. No game assets or combat.
use std::{env,time::Instant};use infinite_core::{World,GridPosition as P,ViewRect,NetworkBudget,Replica};use infinite_server::visibility::Visibility;use tokio::sync::mpsc;
fn point(i:usize,t:u64,mode:&str)->P{let phase=if mode=="static"||i>=512{0}else{t};P{x:(i%64)as i32*512+((phase+i as u64)%8)as i32*128,y:(i/64)as i32*512+((phase*3+i as u64)%4)as i32*64}}
fn view(r:usize,t:u64,mode:&str)->ViewRect{let shift=if mode=="boundary"{(t%16)as i32*512}else{0};let x=(r%4)as i32*4096+8192+shift;let y=(r/4%2)as i32*4096+4096;ViewRect{min:P{x:x-8192,y:y-4096},max:P{x:x+8192,y:y+4096}}}
fn mix(h:&mut u64,n:u32){*h=(*h^u64::from(n)).wrapping_mul(1099511628211);}
fn main(){let mode=env::args().nth(1).unwrap_or("boundary".into());assert!(["static","crossing","boundary"].contains(&mode.as_str()));let mut world=World::default();let ids=(0..1024).map(|i|world.spawn(point(i,0,&mode)).unwrap()).collect::<Vec<_>>();let mut net=Visibility::new(100,16).unwrap();let mut peers=(0..16).map(|r|{let(tx,rx)=mpsc::channel(2);let(id,stream)=net.attach(view(r,0,&mode),tx).unwrap();(id,rx,Replica::new(stream))}).collect::<Vec<_>>();let(mut bytes,mut packets,mut index_ns,mut send_ns,mut decode_ns,mut hash)=(0usize,0,0u128,0u128,0u128,14695981039346656037u64);let mut samples=Vec::new();let mut cache_peak=0usize;
 for t in 1..=120{let start=Instant::now();for(i,&id)in ids.iter().enumerate(){world.set_position(id,point(i,t,&mode)).unwrap();}world.advance_tick().unwrap();net.capture(&world).unwrap();let index=start.elapsed().as_nanos();let start=Instant::now();for(r,p)in peers.iter().enumerate(){net.view(p.0,view(r,t,&mode)).unwrap();}let mut budget=NetworkBudget{work:64,bytes:1024*1024};for _ in 0..4{net.poll(t*50,&mut budget).unwrap();}assert!(net.notices().is_empty());let send=start.elapsed().as_nanos();let mut receive=0;
  for(r,p)in peers.iter_mut().enumerate(){while let Ok(packet)=p.1.try_recv(){let start=Instant::now();let ack=p.2.apply(&packet).unwrap().acknowledgement();receive+=start.elapsed().as_nanos();net.acknowledge(p.0,&ack).unwrap();if t>20{bytes+=packet.len();packets+=1;}}
   let v=view(r,t,&mode);let expected=(0..1024).filter_map(|i|{let p=point(i,t,&mode);v.contains(p).then_some((i,p))}).collect::<Vec<_>>();assert_eq!(p.2.states().len(),expected.len());for(s,(i,point))in p.2.states().iter().zip(expected){assert_eq!(s.entity,ids[i]);assert_eq!(s.position,point);if t>20{mix(&mut hash,i as u32);mix(&mut hash,point.x as u32);mix(&mut hash,point.y as u32);}}if t>20{mix(&mut hash,u32::MAX);}
  }cache_peak=cache_peak.max(net.retained_payload_capacity_bytes());if t>20{index_ns+=index;send_ns+=send;decode_ns+=receive;samples.push((index+send)as f64/1e6);}
 }samples.sort_by(f64::total_cmp);println!("{{\"engine\":\"rust\",\"mode\":\"{mode}\",\"entities\":1024,\"receivers\":16,\"measured_ticks\":100,\"bytes\":{bytes},\"packets\":{packets},\"ack_bytes\":{},\"index_ms\":{},\"send_ms\":{},\"decode_ms\":{},\"server_p99_ms\":{},\"hash\":\"{hash:016x}\",\"retained_cache_payload_peak_bytes\":{cache_peak},\"verified\":true}}",packets*20,index_ns as f64/1e6,send_ns as f64/1e6,decode_ns as f64/1e6,samples[98]);
}
